// SPDX-License-Identifier: MIT
pragma solidity ^0.8.13;

/* Graph of inheritance

            A
           / \
         B   C
        /  \     \
       F     D    E
*/


contract A {
    function foo() public pure virtual returns (string memory) {
        return "A";
    }
}

// Contract B inherits B
contract B is A {
    // Override A.foo()

    function foo() public pure virtual override returns (string memory) {
        return "B";
    }
}

contract C is A {
    function foo() public pure virtual override returns (string memory) {
        return "C";
    }
}

// Contracts can inherirt from multiple parent contracts.
// When a function is called that is defined multiple times in 
// different contracts, parent contracts are searched from 
// right to left, and in-depth-firdt matter

contract D is B, C {
    // D.foo() returns "C"
    // This is because C is the right most parent contract within function foo()

    function foo() public pure override(B, C) returns (string memory) {
        return super.foo();
    }
}

contract E is C, B {
    // E.foo() returns "B"
    //  since B is the right most parent contract with the function foo()

    function foo() public pure override(C, B) returns (string memory) {
        return super.foo();
    }
}

// Inheritance must be ordered from "most base-like" to "most derived".
// Swapping the order of A and B will throw a compilation error.

contract F is A, B {
    function foo() public pure override(A, B) returns (string memory) {
        return super.foo();
    }
}

